@celery_app.task(name="llm_invoke")  # type: ignore[untyped-decorator]  # celery task decorator is unannotated
def llm_invoke(invocation_id: str) -> str:
    """Execute one queued LLM round-trip (ADR 0042, #1511). All failure handling
    lives in `execute_invocation`, which always lands the row terminal.
    """
    session = get_session()
    try:
        return llm_service.execute_invocation(
            session, uuid.UUID(invocation_id), secret_store=get_secret_store()
        )
    finally:
        session.close()

class _FakeProvider:
    model = "fake"

    def __init__(self, *, fail: bool = False) -> None:
        self.fail = fail
        self.calls: list[str] = []

    def complete(self, prompt: str, **_kw: Any) -> LLMResult:
        self.calls.append(prompt)
        if self.fail:
            raise LLMUnavailableError("down")
        return LLMResult(text="ok", input_tokens=3, output_tokens=1)

    def complete_structured(self, prompt: str, *, schema: dict[str, Any], **_kw: Any) -> LLMResult:
        self.calls.append(prompt)
        if self.fail:
            raise LLMUnavailableError("down")
        return LLMResult(text="", parsed={"sql": "SELECT 1"}, input_tokens=3, output_tokens=1)


